-- ═══════════════════════════════════════════════════════════════════
-- sql_agent_demo_business.sql — SQL Agent 演示业务数据种子（自动生成，勿手改）
--
-- 生成器：backend/scripts/gen_sql_agent_demo_seed.py（固定种子 20261008）
-- 目标库：docker 容器 agent-postgres-1 / 宿主端口 5433 / 库 agent_business / 用户 postgres
-- 覆盖  ：schema_config.SCHEMA_CONFIG 纳管的 7 schema × 18 表
--
-- 应用（PowerShell，注意 `"order"` 引号，走 here-string 管道最稳）：
--   Get-Content backend/sql/seeds/sql_agent_demo_business.sql -Raw |
--     docker exec -i agent-postgres-1 psql -U postgres -d agent_business -v ON_ERROR_STOP=1 -q -f -
--
-- 幂等：BEGIN/COMMIT 内按「序列对齐 → 子表删 → 父表删 → 父表到子表重插」执行。
--       第 0 节序列对齐：本种子写入的 17 张 SERIAL 表逐个 setval 到 MAX(id)——
--       历史种子用显式 id 插入、从不推进序列，不对齐则走默认值的插入必然撞 PK。
--       该段不写数据、不改结构，幂等可重复执行。
--       finance.expenses 不删除，走逐行 WHERE NOT EXISTS(date,type,amount)；
--       finance.daily_profit 不删除，从真实订单派生后 ON CONFLICT (date) DO UPDATE。
--       重复应用行数不增长（SERIAL id 会重新分配）。
--
-- 标记约定（删除范围唯一依据）：
--   父锚点  product.categories.name            LIKE '演示分类·%'
--           product.products.sku               LIKE 'SQDEMO-%'
--           customer.customers.name            LIKE '演示客户SQ%'
--           inventory.warehouses.name          LIKE '演示仓·%'
--           crawler.competitor_products.brand  LIKE '演示竞品%'
--           "order".orders.order_no            LIKE 'SQDEMO-%'
--           ai.agent_tasks.session_id          LIKE 'SQDEMO-%'
--   子表    按「引用了上述父锚点」删除（product_tags/inventory/purchase_orders/
--           customer_behavior/product_reviews 按 product_id；order_items/refunds 按
--           order_id；competitor_price 按竞品 id；agent_trace 按 task_id）。
--
-- 安全边界：无 TRUNCATE、无无条件 DELETE、无 DDL、不碰角色与授权；
--           不影响既有 DEMO-SHOW-* 订单 / 演示·% 客户 / 演示品牌 商品。
--
-- 时间口径：全部为相对量（NOW() - INTERVAL 'n days' / CURRENT_DATE - n），
--           任何时刻应用都落在「最近 180 天」窗口内。
-- ═══════════════════════════════════════════════════════════════════

BEGIN;

-- ═══ 0. 序列对齐（先于清理；同一事务内，失败则整体回滚）═══
-- 显式 id 种子会滞后序列 → 不对齐则任何走默认值的插入撞 PK；本段幂等、可重复执行。
-- 不是 DDL、不动任何数据，只把已损坏的序列修正到与数据一致。
SELECT setval(pg_get_serial_sequence('product.categories', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM product.categories), 0), 1));
SELECT setval(pg_get_serial_sequence('product.products', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM product.products), 0), 1));
SELECT setval(pg_get_serial_sequence('product.product_tags', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM product.product_tags), 0), 1));
SELECT setval(pg_get_serial_sequence('"order".orders', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM "order".orders), 0), 1));
SELECT setval(pg_get_serial_sequence('"order".order_items', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM "order".order_items), 0), 1));
SELECT setval(pg_get_serial_sequence('"order".refunds', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM "order".refunds), 0), 1));
SELECT setval(pg_get_serial_sequence('inventory.warehouses', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM inventory.warehouses), 0), 1));
SELECT setval(pg_get_serial_sequence('inventory.inventory', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM inventory.inventory), 0), 1));
SELECT setval(pg_get_serial_sequence('inventory.purchase_orders', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM inventory.purchase_orders), 0), 1));
SELECT setval(pg_get_serial_sequence('customer.customers', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM customer.customers), 0), 1));
SELECT setval(pg_get_serial_sequence('customer.customer_behavior', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM customer.customer_behavior), 0), 1));
SELECT setval(pg_get_serial_sequence('crawler.competitor_products', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM crawler.competitor_products), 0), 1));
SELECT setval(pg_get_serial_sequence('crawler.competitor_price', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM crawler.competitor_price), 0), 1));
SELECT setval(pg_get_serial_sequence('crawler.product_reviews', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM crawler.product_reviews), 0), 1));
SELECT setval(pg_get_serial_sequence('finance.expenses', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM finance.expenses), 0), 1));
SELECT setval(pg_get_serial_sequence('ai.agent_tasks', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM ai.agent_tasks), 0), 1));
SELECT setval(pg_get_serial_sequence('ai.agent_trace', 'id'),
              GREATEST(COALESCE((SELECT MAX(id) FROM ai.agent_trace), 0), 1));

-- ═══ 1. 幂等清理（子表 → 父表；只删本种子标记行）═══
-- 子表：按引用了本种子父锚点删除
DELETE FROM product.product_tags
 WHERE product_id IN (SELECT id FROM product.products WHERE sku LIKE 'SQDEMO-%');
DELETE FROM crawler.product_reviews
 WHERE product_id IN (SELECT id FROM product.products WHERE sku LIKE 'SQDEMO-%');
DELETE FROM inventory.inventory
 WHERE product_id IN (SELECT id FROM product.products WHERE sku LIKE 'SQDEMO-%')
    OR warehouse_id IN (SELECT id FROM inventory.warehouses WHERE name LIKE '演示仓·%');
DELETE FROM inventory.purchase_orders
 WHERE product_id IN (SELECT id FROM product.products WHERE sku LIKE 'SQDEMO-%');
DELETE FROM customer.customer_behavior
 WHERE customer_id IN (SELECT id FROM customer.customers WHERE name LIKE '演示客户SQ%')
    OR product_id IN (SELECT id FROM product.products WHERE sku LIKE 'SQDEMO-%');
DELETE FROM "order".order_items
 WHERE order_id IN (SELECT id FROM "order".orders WHERE order_no LIKE 'SQDEMO-%');
DELETE FROM "order".refunds
 WHERE order_id IN (SELECT id FROM "order".orders WHERE order_no LIKE 'SQDEMO-%')
    OR product_id IN (SELECT id FROM product.products WHERE sku LIKE 'SQDEMO-%');
DELETE FROM crawler.competitor_price
 WHERE product_id IN (SELECT id FROM crawler.competitor_products WHERE brand LIKE '演示竞品%');
DELETE FROM ai.agent_trace
 WHERE task_id IN (SELECT id FROM ai.agent_tasks WHERE session_id LIKE 'SQDEMO-%');

-- 父表：先删引用方，再删锚点自身
DELETE FROM "order".orders WHERE order_no LIKE 'SQDEMO-%';
DELETE FROM customer.customers WHERE name LIKE '演示客户SQ%';
DELETE FROM ai.agent_tasks WHERE session_id LIKE 'SQDEMO-%';
DELETE FROM product.products WHERE sku LIKE 'SQDEMO-%';
DELETE FROM crawler.competitor_products WHERE brand LIKE '演示竞品%';
-- 分类是自引用树：先删二级（parent_id 非空）再删一级
DELETE FROM product.categories WHERE name LIKE '演示分类·%' AND parent_id IS NOT NULL;
DELETE FROM product.categories WHERE name LIKE '演示分类·%';
DELETE FROM inventory.warehouses WHERE name LIKE '演示仓·%';

-- ═══ 2. 插入（父表 → 子表；不显式指定 id，父子引用一律自然键 join）═══

-- ── 2.1 商品分类（8 条 = 4 一级 + 4 二级，parent_id 组树）──
INSERT INTO product.categories (name, parent_id)
SELECT v.name, NULL
FROM (VALUES
  ('演示分类·数码影音'),
  ('演示分类·家居生活'),
  ('演示分类·服饰运动'),
  ('演示分类·个护美妆')
) AS v(name);

INSERT INTO product.categories (name, parent_id)
SELECT v.name, p.id
FROM (VALUES
  ('演示分类·无线耳机', '演示分类·数码影音'),
  ('演示分类·厨房电器', '演示分类·家居生活'),
